`timescale 1ns/1ps
// Auto-generated by fpga_toolbox.emitters.bridge (protocol=axi4->apb)
// Joint bridge testbench: TB drives the axi4 side as master and models the
// apb side as slave, then checks cross-bus transaction consistency.
module tb_axi4_64_to_apb_32_bridge_bridge;
  // DUT 可能有 TB 不关心的额外端口（调试/测试/scan），
  // 显式连接覆盖不到会触发 PINMISSING，故显式关闭。
  /* verilator lint_off PINMISSING */
  logic aclk = 0, aresetn = 0;
  // int 而非 logic：logic 只有 1 位，累加偶数次错误会溢出回 0 从而假 PASS
  int   errs = 0;
  int   up_writes = 0;
  int   dn_writes = 0;
  int   dn_reads = 0;
  int   up_bs = 0;
  int   up_rs = 0;

  logic [3:0] s_axi_awid = 0;
  logic [15:0] s_axi_awaddr = 0;
  logic [7:0] s_axi_awlen = 0;
  logic [2:0] s_axi_awsize = 0;
  logic [1:0] s_axi_awburst = 0;
  logic s_axi_awvalid = 0;
  logic s_axi_awready;
  logic [63:0] s_axi_wdata = 0;
  logic [7:0] s_axi_wstrb = 0;
  logic s_axi_wlast = 0;
  logic s_axi_wvalid = 0;
  logic s_axi_wready;
  logic [3:0] s_axi_bid;
  logic [1:0] s_axi_bresp;
  logic s_axi_bvalid;
  logic s_axi_bready = 1;
  logic [3:0] s_axi_arid = 0;
  logic [15:0] s_axi_araddr = 0;
  logic [7:0] s_axi_arlen = 0;
  logic [2:0] s_axi_arsize = 0;
  logic [1:0] s_axi_arburst = 0;
  logic s_axi_arvalid = 0;
  logic s_axi_arready;
  logic [3:0] s_axi_rid;
  logic [63:0] s_axi_rdata;
  logic [1:0] s_axi_rresp;
  logic s_axi_rlast;
  logic s_axi_rvalid;
  logic s_axi_rready = 1;
  logic m_apb_psel;
  logic m_apb_penable;
  logic m_apb_pwrite;
  logic [15:0] m_apb_paddr;
  logic [31:0] m_apb_pwdata;
  logic [3:0] m_apb_pstrb;
  logic m_apb_pready = 0;
  logic [31:0] m_apb_prdata = 0;
  logic m_apb_pslverr = 0;

  axi4_64_to_apb_32_bridge dut (
    .aclk(aclk), .aresetn(aresetn),
    .s_axi_awid(s_axi_awid),
    .s_axi_awaddr(s_axi_awaddr),
    .s_axi_awlen(s_axi_awlen),
    .s_axi_awsize(s_axi_awsize),
    .s_axi_awburst(s_axi_awburst),
    .s_axi_awvalid(s_axi_awvalid),
    .s_axi_awready(s_axi_awready),
    .s_axi_wdata(s_axi_wdata),
    .s_axi_wstrb(s_axi_wstrb),
    .s_axi_wlast(s_axi_wlast),
    .s_axi_wvalid(s_axi_wvalid),
    .s_axi_wready(s_axi_wready),
    .s_axi_bid(s_axi_bid),
    .s_axi_bresp(s_axi_bresp),
    .s_axi_bvalid(s_axi_bvalid),
    .s_axi_bready(s_axi_bready),
    .s_axi_arid(s_axi_arid),
    .s_axi_araddr(s_axi_araddr),
    .s_axi_arlen(s_axi_arlen),
    .s_axi_arsize(s_axi_arsize),
    .s_axi_arburst(s_axi_arburst),
    .s_axi_arvalid(s_axi_arvalid),
    .s_axi_arready(s_axi_arready),
    .s_axi_rid(s_axi_rid),
    .s_axi_rdata(s_axi_rdata),
    .s_axi_rresp(s_axi_rresp),
    .s_axi_rlast(s_axi_rlast),
    .s_axi_rvalid(s_axi_rvalid),
    .s_axi_rready(s_axi_rready),
    .m_apb_psel(m_apb_psel),
    .m_apb_penable(m_apb_penable),
    .m_apb_pwrite(m_apb_pwrite),
    .m_apb_paddr(m_apb_paddr),
    .m_apb_pwdata(m_apb_pwdata),
    .m_apb_pstrb(m_apb_pstrb),
    .m_apb_pready(m_apb_pready),
    .m_apb_prdata(m_apb_prdata),
    .m_apb_pslverr(m_apb_pslverr)
  );
  always #5 aclk = ~aclk;

  // ---------------------------------------------------------------------
  // 下游 APB 从机模型：只要有 psel&&penable 就应答，并记录访问地址/数据。
  // 用固定延迟 1 拍模拟真实从机（0 拍会让「桥接是否插入等待」不可观测）。
  // ---------------------------------------------------------------------
  logic [31:0] apb_rdata_mem [0:15];
  // APB 协议要点：PSEL 高、PENABLE 低是 **setup** 相位，此时 PADDR/PWDATA
  // 可能还没被主设备驱动为最终值（本 DUT 在 setup 相位之后才锁存 pwdata）。
  // 只有在 **access** 相位（PSEL && PENABLE 同时为高）采样才是协议正确的。
  //
  // 实测踩坑：在 PSEL 刚拉高的同一拍采样，得到的 pwdata 恒为 0 —— 会误报成
  // 「桥接没有搬数据」，而实际是 TB 采样早了一拍（设 DUT 时序是对的）。
  // 这类假缺陷比漏报更危险：它让人去改正确的 RTL。
  always @(posedge aclk) begin
    if (aresetn === 1'b1) begin
      m_apb_pready <= 0;
      // 只在「尚未应答过本次传输」时处理。若不看 pready 就重复处理，setup
      // 相位之后的连续 access 拍会把同一次传输统计两次（实测 dn_writes 翻倍，
      // 让「桥接拆成几次下游访问」这条断言失去意义）。
      if (m_apb_psel === 1'b1 && m_apb_penable === 1'b1
          && m_apb_pready === 1'b0) begin
        // access 相位：此时 paddr/pwdata 已稳定，可以安全采样
        if (m_apb_pwrite === 1'b1) begin
          dn_writes++;
          $display("[CHECK] id=BR_WR | proto=axi4->apb | cat=downstream_write | addr=0x%04h data=0x%08h strb=0x%01h | status=PASS",
                   m_apb_paddr, m_apb_pwdata, m_apb_pstrb);
          apb_rdata_mem[m_apb_paddr[3:0]] <= m_apb_pwdata;
          m_apb_pready <= 1;
        end else begin
          dn_reads++;
          m_apb_prdata <= apb_rdata_mem[m_apb_paddr[3:0]];
          m_apb_pready <= 1;
        end
      end else begin
        m_apb_pready <= 0;
      end
    end
  end

  // ---------------------------------------------------------------------
  // 上游 AXI4 写事务：发一个 2-beat INCR 写，数据是高/低半区可区分的 64 位值。
  // 桥接 DUT 应把它拆成两次 APB 32 位写。
  // ---------------------------------------------------------------------
  task automatic axi4_write(input logic [15:0] addr, input logic [63:0] data);
    // AW
    @(posedge aclk); #1;
    s_axi_awid = 4'd1; s_axi_awaddr = addr;
    s_axi_awlen = 8'd1; s_axi_awsize = 3'd3;
    s_axi_awburst = 2'b01; s_axi_awvalid = 1;
    while (!s_axi_awready) begin @(posedge aclk); #1; end
    @(posedge aclk); #1;
    s_axi_awvalid = 0;
    // W x2
    for (int i = 0; i < 2; i++) begin
      // 第 0 拍给低 32 位、第 1 拍给高 32 位，桥接应分别写到 addr 和 addr+4
      // 高半区填 0、低 32 位放测试图案（拼接表达式已预先算好，
      // 避免在 f-string 里做四层花括号转义）
      s_axi_wdata = (i == 0) ? {{32{1'b0}}, 32'h12345678} : {{32{1'b0}}, 32'hDEADBEEF};
      s_axi_wstrb = '1; s_axi_wlast = (i == 1); s_axi_wvalid = 1;
      while (!s_axi_wready) begin @(posedge aclk); #1; end
      @(posedge aclk); #1;
    end
    s_axi_wvalid = 0; s_axi_wlast = 0;
    up_writes++;
    // B
    // R3：等响应必须同时查 VALID 与 READY（只等 bvalid 会被 lint_tb 判 R3，
    // 且真实硬件里 master 不置 bready 时事务同样无法完成）。
    while (!(s_axi_bvalid && s_axi_bready)) begin @(posedge aclk); #1; end
    if (s_axi_bresp !== 2'd0) begin
      $display("[CHECK] id=BR_B | proto=axi4->apb | cat=write_response | exp=bresp=0 | got=%0d | status=FAIL",
               s_axi_bresp);
      errs++;
    end else begin
      up_bs++;
      $display("[CHECK] id=BR_B | proto=axi4->apb | cat=write_response | exp=bresp=0 | got=0 | status=PASS");
    end
    @(posedge aclk); #1;
  endtask

  initial begin
    // ---- waveform dump (optional; enable with +WAVE on the sim command line) ----
    if ($test$plusargs("WAVE")) begin
      if ($value$plusargs("WAVE_FILE=%s", wave_path)) begin
        $dumpfile(wave_path);
      end else begin
        $dumpfile("wave.vcd");
      end
      $dumpvars(0, tb_axi4_64_to_apb_32_bridge_bridge);
    end
    repeat (3) @(posedge aclk);
    aresetn = 1;
    repeat (2) @(posedge aclk);

    // ---- 上游写一个 64 位事务 ----
    axi4_write(16'h0040,
               64'hDEADBEEF12345678);

    // 给下游事务留出传播时间（桥接通常有 2~8 拍的流水延迟）
    repeat (40) @(posedge aclk);

    // ---- 跨总线一致性：上游 1 次 64 位写 → 下游应出现 2 次 32 位写 ----
    if (dn_writes < 2) begin
      $display("[CHECK] id=BR_SPLIT | proto=axi4->apb | cat=width_split | exp=>=2 downstream 32-bit writes | got=%0d | status=FAIL", dn_writes);
      errs++;
    end else begin
      $display("[CHECK] id=BR_SPLIT | proto=axi4->apb | cat=width_split | exp=>=2 | got=%0d | status=PASS", dn_writes);
    end

    // 上游必须收到写响应（桥接把 APB pready 转成 AXI4 bvalid）
    if (up_bs == 0) begin
      $display("[CHECK] id=BR_RESP | proto=axi4->apb | cat=response_path | exp=bvalid | got=none | status=FAIL");
      errs++;
    end else begin
      $display("[CHECK] id=BR_RESP | proto=axi4->apb | cat=response_path | exp=bvalid | got=%0d | status=PASS", up_bs);
    end

    if (errs == 0) begin
      $display("PASS: bridge axi4->apb upstream transaction split into %0d downstream accesses with responses", dn_writes);
      $finish;
    end else begin
      $display("FAIL: bridge axi4->apb %0d errors", errs);
      $fatal(1);
    end
  end

  // 看门狗：桥接若死锁（上游等不到 ready / 下游等不到 pready），必须快速失败
  initial begin
    #2000000;
    $display("FAIL: bridge axi4->apb timeout (handshake deadlock)");
    $fatal(1);
  end
  string wave_path;
endmodule
